<template><AppShell title="订单详情" back footer><StateView :loading="loading" :error="error" :count="order?1:0" @retry="load" /><template v-if="order&&!error&&!loading"><view class="order-hero"><view v-if="!isItem(order)" class="progress-ring" :style="{background:'conic-gradient(#ffe433 '+Math.max(0,Math.min(100,Number(order.progress)||0))+'%, #fff 0)'}"><view class="progress-ring-center">{{order.progress}}<text>%</text></view></view><view><text class="title">{{labels[order.status]}}</text><text class="order-hint">{{statusHint}}</text></view></view><view class="pad"><view class="card row"><GameArt variant="mini" class="mini-cover" :game="order.game" /><view class="flex-1 stack"><text class="bold">{{order.title}}</text><text class="muted tiny">{{isItem(order)?order.itemCategory+' · '+order.quantity+' 件':order.currentRank+' → '+order.targetRank}}</text><text class="muted tiny">{{gameServerLabel(order)}}</text><text v-if="order.pricingMode==='UNIT'" class="muted tiny">单价 ¥{{money(order.unitPriceCents)}} × {{order.quantity}} 件</text></view><view class="stack"><text class="tiny muted">{{["WAIT_PAY","CANCELLED"].includes(order.status)?"订单金额":"实付"}}</text><text class="price">¥{{money(order.amountCents)}}</text></view></view><view v-if="!paymentsEnabled" class="notice" style="margin-bottom:12px"><AppIcon class="app-icon" name="info" :size="17" /><text>支付及资金操作暂未开放；待付款订单可取消，订单信息与聊天仍可查看。</text></view><view v-if="order.paymentMode==='SIMULATED'" class="notice" style="margin-bottom:12px"><AppIcon class="app-icon" name="info" :size="17" /><text>测试订单，不涉及真实支付或到账</text></view><view v-if="!isItem(order)" class="card"><view class="row between"><text class="field-label">历史代练进度</text><text class="bold">{{order.progress}}%</text></view><view class="step-line"><view :style="{width:order.progress+'%'}" /></view><view class="rank-row"><view><text class="muted tiny">起始</text><text>{{order.currentRank||'原进度'}}</text></view><view><text class="muted tiny">目标</text><text>{{order.targetRank}}</text></view><view><text class="muted tiny">时限</text><text>{{order.durationHours}} 小时</text></view></view><text class="field-label section">进度记录</text><view v-for="p in order.updates" :key="p.id" class="timeline-row"><view class="timeline-dot" /><view class="flex-1"><text class="bold">{{p.note}}</text><text class="muted tiny" style="display:block">{{date(p.createdAt)}} · {{p.percent}}%</text><view class="evidence"><image v-for="src in images(p.images)" :key="src" :src="imageUrl(src)" mode="aspectFill" @click="preview(p.images,src)" /></view></view></view><text v-if="!order.updates.length" class="muted">服务开始后，这里会显示每次进度更新。</text></view><view v-if="paymentsEnabled&&!isBuyer&&!isItem(order)&&order.status==='IN_PROGRESS'" class="card"><text class="field-label">同步进度</text><view class="field-row"><text>完成进度（%）</text><input v-model="progress.percent" @focus="progressEditing.percent=true" @blur="progress.percent=$event.detail.value;progressEditing.percent=false" type="number" placeholder="0–100" /></view><textarea v-model="progress.note" @focus="progressEditing.note=true" @blur="progress.note=$event.detail.value;progressEditing.note=false" class="textarea section" placeholder="说明当前段位、已完成的任务等" maxlength="1000" /><view class="section"><UploadImages purpose="DELIVERY" v-model="progress.images" @busy="uploading=$event" /></view><text class="muted tiny">进度填 100% 并上传成果后，订单进入待验收。</text><button class="ui-button btn wide section" :disabled="busy||uploading" @click="updateProgress">提交进度</button></view><view v-if="isItem(order)" class="card"><text class="field-label">道具介绍</text><text class="summary-text" style="display:block">{{order.itemDetails}}</text><text v-if="order.deliveryTerms" class="summary-text section" style="display:block">{{order.deliveryTerms}}</text><image v-for="src in images(order.detailImages)" :key="src" class="snapshot-detail-image" :src="imageUrl(src)" mode="widthFix" @click="preview(order.detailImages,src)" /><view v-if="order.delivery" class="section"><text class="field-label">卖家交付凭证</text><text class="summary-text" style="display:block">{{order.delivery.note}}</text><text class="muted tiny">{{date(order.delivery.createdAt)}}</text><view class="evidence"><image v-for="src in images(order.delivery.images)" :key="src" :src="imageUrl(src)" mode="aspectFill" @click="preview(order.delivery.images,src)" /></view></view><text v-else class="muted tiny" style="display:block;margin-top:12px">{{order.status==='WAIT_PAY'?'付款后才进入道具交付流程':'卖家暂未提交交付凭证'}}</text></view><view v-if="isItem(order)&&paymentsEnabled&&!isBuyer&&order.status==='WAIT_DELIVERY'" class="card"><text class="field-label">提交道具交付</text><textarea v-model="delivery.note" @blur="delivery.note=$event.detail.value" class="textarea section" maxlength="1000" placeholder="说明交付的道具与数量（至少 5 字）" /><UploadImages purpose="DELIVERY" v-model="delivery.images" @busy="uploading=$event" /><button class="ui-button btn wide section" :disabled="busy||uploading" @click="deliver">提交交付凭证</button></view><view v-if="order.aftersale" class="card"><view class="row between"><text class="field-label">售后记录</text><text class="tag">{{labels[order.aftersale.status]}}</text></view><text class="summary-text">{{order.aftersale.reason}}：{{order.aftersale.description}}</text><text v-if="order.aftersale.reply" class="summary-text" style="display:block;margin-top:8px">平台回复：{{order.aftersale.reply}}</text></view><view v-if="paymentsEnabled&&isBuyer&&order.status==='COMPLETED'&&!order.reviewed" class="card"><text class="field-label">为这次交易打个分</text><view class="stars-row"><button class="ui-button" v-for="n in 5" :key="n" @click="stars=n" :aria-label="n+'星'">{{n<=stars?'★':'☆'}}</button></view><textarea v-model="reviewText" @blur="reviewText=$event.detail.value" class="textarea" maxlength="1000" placeholder="说说你的体验（至少 2 个字）" /><button class="ui-button btn wide section" :disabled="busy" @click="review">提交评价</button></view><view class="card"><text class="field-label">订单信息</text><view class="field-row" @click="copy"><text>订单编号</text><text class="tiny">{{order.orderNo}} <AppIcon class="app-icon" name="copy" :size="13" /></text></view><view class="field-row"><text>下单时间</text><text class="muted">{{date(order.createdAt)}}</text></view><view class="field-row"><text>卖家</text><text>{{order.workerName}}</text></view><view class="field-row"><text>用户</text><text>{{order.buyerName}}</text></view><view v-if="order.note" class="section"><text class="muted">需求说明：{{order.note}}</text></view></view><text v-if="actionError" class="field-error">{{actionError}}</text><button v-if="['WAIT_PAY','REFUNDING','REFUND_EXCEPTION'].includes(order.status)" class="ui-button btn outline wide section" :disabled="busy||loading" @click="load">刷新订单状态</button></view></template><template #footer><template v-if="order&&!error&&!loading"><button class="ui-button btn outline" @click="chatWith(isBuyer?order.workerId:order.buyerId,order.listingId)">联系{{isBuyer?'卖家':'买家'}}</button><button v-if="paymentsEnabled&&order.status==='WAIT_PAY'&&isBuyer" class="ui-button btn" :disabled="busy" @click="pay">去付款</button><button v-else-if="paymentsEnabled&&order.status==='WAIT_START'&&!isBuyer" class="ui-button btn" :disabled="busy" @click="action('start')">开始服务</button><button v-else-if="paymentsEnabled&&['REVIEW','WAIT_CONFIRM'].includes(order.status)&&isBuyer" class="ui-button btn" :disabled="busy" @click="action('confirm')">确认收货</button><button v-else-if="paymentsEnabled&&isBuyer&&['WAIT_START','IN_PROGRESS','WAIT_DELIVERY'].includes(order.status)&&!order.aftersale" class="ui-button btn outline" @click="go('aftersale/index',{id:order.id})">申请售后</button><button v-else-if="order.status==='WAIT_PAY'&&!isBuyer" class="ui-button btn outline" :disabled="busy" @click="action('cancel')">取消未付款订单</button></template></template><view v-if="!loading&&!error&&order?.status==='WAIT_PAY'&&isBuyer" class="pad"><button class="ui-button text-button muted" @click="action('cancel')">取消未付款订单</button></view><view v-if="paymentsEnabled&&!loading&&!error&&isBuyer&&['REVIEW','WAIT_CONFIRM'].includes(order?.status)&&!order.aftersale" class="pad"><button class="ui-button text-button muted" @click="go('aftersale/index',{id:order.id})">交付有问题？申请售后</button></view></AppShell></template>
<script setup>
import {gameServerLabel} from '../../lib/playerTrade'
import {ref,reactive,computed} from 'vue';import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import AppIcon from '../../components/AppIcon.vue';import GameArt from '../../components/GameArt.vue';import StateView from '../../components/StateView.vue';import UploadImages from '../../components/UploadImages.vue';import {request,session,loadMe,loadConfig,requireLogin,money,date,labels,images,imageUrl,go,confirm,chatWith,payOrder,toast} from '../../lib/api';import {previewMedia} from '../../lib/media';import {isItem} from '../../lib/playerTrade';import {retryIntent,completeIntent} from '../../lib/retryIntent'
const delivery=reactive({note:'',images:[]});const id=ref(''),order=ref(null),loading=ref(false),error=ref(''),actionError=ref(''),busy=ref(false),uploading=ref(false),stars=ref(5),reviewText=ref(''),progress=reactive({percent:0,note:'',images:[]});const paymentsEnabled=computed(()=>session.config?.paymentsEnabled!==false);const isBuyer=computed(()=>order.value?.buyerId===session.user?.id);const statusHint=computed(()=>({WAIT_PAY:paymentsEnabled.value?'付款后，卖家按约交付':'支付暂未开放，可查看或取消订单',WAIT_DELIVERY:'已付款，等待卖家按约交付道具',WAIT_CONFIRM:'核对实际收到的道具，再确认收货',WAIT_START:'历史服务，等待开始',IN_PROGRESS:'每一步进展，都在这里同步',REVIEW:'请查看成果截图，再确认验收',COMPLETED:'服务已完成，感谢你的信任',AFTERSALE:'平台正在协助处理，交付已暂停',REFUNDED:'退款处理完成',REFUNDING:'退款已受理，等待微信原路退回',REFUND_EXCEPTION:'退款遇到异常，平台正在跟进，请勿重复付款',CANCELLED:'订单已关闭'}[order.value?.status]||''));onLoad(q=>id.value=q.id);onShow(()=>{active=true;if(requireLogin())load()});onHide(stopPolling);onUnload(stopPolling)
const progressEditing=reactive({note:false,percent:false})
let active=true,pollTimer,pollResolve,pollEpoch=0,loadVersion=0;function stopPolling(){active=false;pollEpoch++;loadVersion++;clearTimeout(pollTimer);pollResolve?.();pollResolve=null}
async function pollPayment(){const epoch=++pollEpoch;for(let i=0;i<8&&active&&epoch===pollEpoch;i++){const d=await request('/boost/orders/'+id.value);if(!active||epoch!==pollEpoch)return;order.value=d;if(d.status!=='WAIT_PAY')return;await new Promise(resolve=>{pollResolve=resolve;pollTimer=setTimeout(()=>{pollResolve=null;resolve()},1500)})}if(active&&epoch===pollEpoch&&order.value?.status==='WAIT_PAY')actionError.value='渠道结果仍在确认，请稍后点击刷新；无需重复付款'}
async function load(background=false){
 const version=++loadVersion,token=session.token,orderId=id.value,draftPercent=progress.percent
 const syncPercent=!order.value||Number(draftPercent)===Number(order.value.progress)
 const current=()=>active&&version===loadVersion&&token===session.token&&orderId===id.value
 // Keep native inputs mounted during a mutation refresh; uni-app throttles input model updates.
 if(background!==true)loading.value=true
 error.value=''
 try{
  await Promise.all([loadMe(),loadConfig()]);if(!current())return
  const result=await request('/boost/orders/'+orderId);if(!current())return
  order.value=result
  if(syncPercent&&!progressEditing.percent&&progress.percent===draftPercent)progress.percent=result.progress
 }catch(e){if(current()){order.value=null;error.value=e.message}}finally{if(current())loading.value=false}
}
async function mutate(fn){if(busy.value)return;busy.value=true;actionError.value='';try{await fn();if(active)await load(true)}catch(e){actionError.value=e.message;toast(e.message)}finally{busy.value=false}}
async function action(type){const message={confirm:'确认已实际收到约定道具？确认收货后订单完成并结算给卖家。',cancel:'确定取消这个未付款订单？',start:'请先确认服务目标和用户要求，确定开始服务？'}[type];if(await confirm(message))await mutate(()=>request(`/boost/orders/${id.value}/action`,'POST',{action:type}))}
async function pay(){await mutate(async()=>{if(await payOrder(id.value))await pollPayment()})}
async function updateProgress(){
 const submitted={percent:Number(progress.percent),note:progress.note,images:[...progress.images]}
 await mutate(async()=>{
  await request(`/boost/orders/${id.value}/progress`,'POST',submitted)
  if(!progressEditing.note&&progress.note===submitted.note)progress.note=''
  if(JSON.stringify(progress.images)===JSON.stringify(submitted.images))progress.images=[]
  toast('进度已同步')
 })
}
async function deliver(){if(uploading.value)return;const submitted={note:delivery.note,images:[...delivery.images]},intent=retryIntent('delivery_'+id.value,submitted);await mutate(async()=>{await request(`/boost/orders/${id.value}/delivery`,'POST',{...submitted,requestKey:intent.requestKey});completeIntent(intent);toast('交付凭证已提交，等待买家确认')})}
async function review(){await mutate(()=>request(`/boost/orders/${id.value}/review`,'POST',{stars:stars.value,content:reviewText.value}))}
function preview(all,current){previewMedia(images(all),current)}function copy(){uni.setClipboardData({data:order.value.orderNo})}
</script>
<style scoped>.snapshot-detail-image{display:block;width:100%;margin-top:12px;border-radius:8px}.order-hero{display:flex;align-items:center;gap:18px;background:#fff1a0;padding:25px 20px}.progress-ring{width:64px;height:64px;border:6px solid #fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:20px;font-weight:800}.progress-ring text{font-size:10px}.order-hint{display:block;font-size:11px;color:#82722f;margin-top:4px}.rank-row{display:flex;justify-content:space-between;margin-top:16px;font-size:12px;text-align:center}.rank-row>view{display:flex;flex-direction:column;gap:3px;flex:1}.rank-row>view+view{border-left:1px solid #eee}.timeline-row{display:flex;gap:12px;padding:10px 0;position:relative;font-size:13px}.timeline-dot{width:9px;height:9px;border-radius:50%;background:var(--yellow);margin-top:5px;flex-shrink:0}.timeline-row:not(:last-child)::before{content:'';position:absolute;left:4px;top:24px;bottom:-4px;width:1px;background:#ece6c5}.evidence{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}.evidence image{width:90px;height:68px;border-radius:8px}.stars-row{display:flex;margin:12px 0;color:#d4a600}.stars-row button{font-size:30px;width:45px}.order-hero{padding:16px;gap:16px;background:#fff4ac}.progress-ring{width:76px;height:76px;border:0;padding:7px;flex-shrink:0}.progress-ring-center{height:62px;width:62px;display:flex;align-items:center;justify-content:center;border-radius:50%;background:#fff4ac}.order-hero+.pad{padding-top:0}.order-hero+.pad>.card:first-child{border-radius:12px;margin-top:0}.timeline-row{padding:10px 0}.order-hero .title{font-size:21px}.evidence image{width:112px;height:82px}.rank-row{margin-top:12px}</style>
